  /** Bump khi tải bản dịch / đổi ngôn ngữ để navSections dịch lại (translate.instant không reactive). */
  private readonly langTick = signal(0);

  /** Nhóm taxonomy → HrmNavSection: overview (leaf) + các nhóm là mục cha có con (gập/mở). */
  protected readonly navSections = computed<HrmNavSection[]>(() => {
    this.langTick();
    const t = (k: string) => this.translate.instant(k);
    return [
      { items: [{ key: 'overview', label: t('sg.nav.overview'), route: 'overview', icon: IconLayoutDashboard }] },
      { items: this.groups.map((g) => ({
          key: g.key,
          label: t(g.labelKey),
          icon: this.groupIcons[g.key],
          keywords: this.groupKeywords[g.key],
          children: g.items.map((it) => ({
            key: it.route,
            label: it.labelKey ? t(it.labelKey) : (it.label ?? ''),
            route: it.route,
          })),
        })) },
    ];
  });

  /** Chuỗi ô tìm kiếm side nav (dịch lại theo langTick — translate.instant không reactive). */
  protected readonly tSearch = computed(() => { this.langTick(); return this.translate.instant('sg.nav.search'); });
  protected readonly tSearchClear = computed(() => { this.langTick(); return this.translate.instant('sg.nav.searchClear'); });
  protected readonly tSearchEmpty = computed(() => { this.langTick(); return this.translate.instant('sg.nav.searchEmpty'); });

  protected readonly currentKey = signal(this.keyFromUrl(this.router.url));

  constructor() {
    this.router.events.pipe(
      filter((e): e is NavigationEnd => e instanceof NavigationEnd),
      takeUntilDestroyed(),
    ).subscribe((e) => this.currentKey.set(this.keyFromUrl(e.urlAfterRedirects)));

    // navSections dịch lại khi bản dịch tải xong (async loader) hoặc đổi ngôn ngữ.
    merge(this.translate.onLangChange, this.translate.onDefaultLangChange, this.translate.onTranslationChange)
      .pipe(takeUntilDestroyed())
      .subscribe(() => this.langTick.update((n) => n + 1));

    // Đăng ký lệnh điều hướng cho hộp tìm lệnh (Ctrl/⌘+K): mỗi trang doc = 1 lệnh.
    const palette = inject(HrmCommandPaletteService);
    palette.register(
      this.groups.flatMap((g) =>
        g.items
          .filter((it) => !!it.label || !!it.labelKey)
          .map((it) => ({
            key: 'nav:' + it.route,
            label: it.labelKey ? this.translate.instant(it.labelKey) : it.label!,
            group: this.translate.instant(g.labelKey),
            action: () => this.navTo(it.route),
          })),
      ),
    );
  }

  private keyFromUrl(url: string): string {
    return url.replace(/^\/styleguide\/?/, '').split(/[?#]/)[0] || 'overview';
  }

  protected onNav(it: HrmNavItem): void { if (it.route) this.navTo(it.route); }
  protected navTo(route: string): void { this.router.navigateByUrl('/styleguide/' + route); }
