import { EnvironmentProviders, makeEnvironmentProviders } from '@angular/core';
import { provideTablerIconConfig } from '@tabler/icons-angular';

/** ĐỘ MẢNH NÉT ICON chuẩn của design system (Tabler stroke-width).
 *  Tabler mặc định = 2 (đậm); DS dùng 1.5 (mảnh). Đây là SSOT — đổi Ở ĐÂY, mọi app
 *  áp dụng DS (gọi provideHrmIcons) sẽ đồng bộ theo sau khi build lại bản DS này. */
export const HRM_ICON_STROKE = 1.5;

/** Provider icon chuẩn DS — app đặt trong providers[] THAY CHO việc tự gọi
 *  provideTablerIconConfig. Nhờ vậy độ mảnh nét do DS kiểm soát tập trung:
 *  đổi HRM_ICON_STROKE trong lib → mọi project dùng bản lib này tự đổi theo.
 *
 *  // app.config.ts
 *  providers: [ provideHrmIcons(), provideTablerIcons({ ...icons }) ]
 *
 *  Muốn 1 app khác độ mảnh: truyền tham số — provideHrmIcons(2). */
export function provideHrmIcons(stroke: number = HRM_ICON_STROKE): EnvironmentProviders {
  return makeEnvironmentProviders([
    provideTablerIconConfig({ stroke }),
  ]);
}
