import { Component, computed, signal } from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';

/** 1 mục version trong manifest. */
interface VersionItem {
  /** Số version, VD "0.0.1". */
  version: string;
  /** Base URL phục vụ bản này — "/" (latest ở gốc) hoặc "/version/0.0.1/" (bản ghim). */
  url: string;
  /** Nhãn hiển thị (mặc định = version). */
  label?: string;
  /** Thẻ phụ, VD "latest" / "experimental". */
  tag?: string;
}
interface VersionManifest { current: string; versions: VersionItem[]; }

/** Fallback khi chưa có /versions.json (môi trường dev) — chỉ bản hiện tại. */
const FALLBACK: VersionManifest = {
  current: '0.0.1',
  versions: [{ version: '0.0.1', url: '/', label: '0.0.1', tag: 'experimental' }],
};

/** sg-version-switcher — dropdown chọn PHIÊN BẢN design system (kiểu ng.ant.design).
 *  Mỗi version = 1 build tĩnh riêng phục vụ ở base URL riêng ("/" latest · "/version/X/" ghim).
 *  Chọn version → ĐIỀU HƯỚNG FULL-PAGE sang base đó, GIỮ NGUYÊN sub-path trang đang xem.
 *  Manifest luôn fetch từ GỐC (/versions.json) nên cả bản cũ cũng thấy danh sách mới nhất. */
@Component({
  selector: 'sg-version-switcher',
  imports: [TablerIconComponent],
  template: `
    <button type="button" class="vs-btn" [class.on]="open()"
      aria-label="Chọn phiên bản" [attr.aria-expanded]="open()"
      (click)="open.set(!open())">
      <span class="vs-cur">{{ currentVersion() }}</span>
      @if (currentTag(); as t) { <span class="vs-tag">{{ t }}</span> }
      <tabler-icon class="vs-chev" icon="chevron-down" [size]="15" />
    </button>

    @if (open()) {
      <div class="vs-backdrop" (click)="open.set(false)"></div>
      <div class="vs-menu" role="listbox">
        @for (v of versions(); track v.version) {
          <button type="button" class="vs-item" role="option"
            [class.on]="v.version === currentVersion()"
            [attr.aria-selected]="v.version === currentVersion()"
            (click)="select(v)">
            <span class="vs-item-v">{{ v.label || v.version }}</span>
            @if (v.tag) { <span class="vs-item-tag">{{ v.tag }}</span> }
            @if (v.version === currentVersion()) { <tabler-icon class="vs-item-ck" icon="check" [size]="15" /> }
          </button>
        }
      </div>
    }
  `,
  styles: [`
    /* Pill ghim góc TRÊN phải — vị trí switcher kiểu ng.ant.design (không đè nút config ở góc dưới). */
    :host { position: fixed; top: 14px; right: 18px; z-index: 800; display: inline-flex; }

    .vs-btn {
      display: inline-flex; align-items: center; gap: 6px;
      height: 34px; padding: 0 10px 0 12px;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface); box-shadow: var(--shadow-regular-xs);
      cursor: pointer; font-family: var(--font-sans);
      color: var(--text-strong);
      transition: border-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out);
    }
    .vs-btn:hover, .vs-btn.on { border-color: var(--primary-base); box-shadow: var(--shadow-regular-sm); }
    .vs-cur { font-size: var(--fs-13); font-weight: 600; font-variant-numeric: tabular-nums; }
    .vs-tag {
      font-size: var(--fs-11, 11px); font-weight: 500; line-height: 1;
      padding: 2px 6px; border-radius: var(--radius-full, 999px);
      background: var(--primary-bg-subtle); color: var(--primary-base);
    }
    .vs-chev { color: var(--text-soft); }

    .vs-backdrop { position: fixed; inset: 0; z-index: var(--z-dropdown, 1000); }
    .vs-menu {
      position: absolute; top: calc(100% + 8px); right: 0; z-index: var(--z-popover, 1010);
      min-width: 190px; max-height: min(60vh, 420px); overflow-y: auto;
      padding: 6px; display: flex; flex-direction: column; gap: 2px;
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md);
    }
    .vs-item {
      display: flex; align-items: center; gap: 8px;
      padding: 8px 10px; border: 0; border-radius: var(--radius-md);
      background: transparent; cursor: pointer; text-align: left;
      font-family: var(--font-sans); font-size: var(--fs-14); color: var(--text-body);
      transition: background var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out);
    }
    .vs-item:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .vs-item.on { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: 600; }
    .vs-item-v { flex: 1; font-variant-numeric: tabular-nums; }
    .vs-item-tag { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vs-item.on .vs-item-tag { color: var(--primary-base); }
    .vs-item-ck { color: var(--primary-base); }
  `],
})
export class SgVersionSwitcher {
  protected readonly open = signal(false);
  private readonly manifest = signal<VersionManifest>(FALLBACK);
  protected readonly versions = computed(() => this.manifest().versions);

  /** Version đang xem = suy từ URL (/version/X/… → X), nếu không thì manifest.current. */
  protected readonly currentVersion = computed(() => {
    const m = /^\/version\/([^/]+)\//.exec(this.pathname());
    return m ? m[1] : this.manifest().current;
  });
  protected readonly currentTag = computed(() => {
    const cur = this.currentVersion();
    return this.versions().find((v) => v.version === cur)?.tag ?? null;
  });
  private readonly pathname = signal<string>(this.readPathname());

  constructor() {
    this.loadManifest();
  }

  private readPathname(): string {
    try { return window.location.pathname; } catch { return '/'; }
  }

  /** Manifest LUÔN lấy từ GỐC (/versions.json) → bản cũ vẫn thấy danh sách mới nhất. */
  private loadManifest(): void {
    try {
      fetch('/versions.json', { cache: 'no-cache' })
        .then((r) => (r.ok ? r.json() : null))
        .then((data: VersionManifest | null) => {
          if (data && Array.isArray(data.versions) && data.versions.length) this.manifest.set(data);
        })
        .catch(() => { /* giữ FALLBACK — dev/no-manifest */ });
    } catch { /* SSR/no-window */ }
  }

  /** Chọn version → điều hướng full-page sang base URL bản đó, giữ nguyên sub-path hiện tại. */
  protected select(v: VersionItem): void {
    if (v.version === this.currentVersion()) { this.open.set(false); return; }
    const base = v.url.replace(/\/+$/, '');            // '' cho gốc, '/version/0.0.1' cho bản ghim
    let path = this.pathname().replace(/^\/version\/[^/]+/, ''); // bỏ prefix version cũ (nếu có)
    if (!path.startsWith('/')) path = '/' + path;
    try { window.location.assign(base + path + window.location.search); } catch { /* no-window */ }
  }
}
