interface NavItem {
  /** Stable unique key — required when item has children (drives popup state). */
  key?: string;
  label: string;
  icon: string;
  route?: string;
  perm?: string;
  children?: NavItem[];
  comingSoon?: boolean;
}

interface NavSection {
  /** Stable key dùng cho localStorage persist trạng thái collapsed. */
  key?: string;
  header?: string;
  items: NavItem[];
  /** Default open khi user chưa có pref. */
  defaultOpen?: boolean;
}

