  protected async pickLang(code: LangCode): Promise<void> {
    await this.i18n.switch(code);
    this.closeLang();
  }

  // ===== Sidebar state =====
  /** Sidebar collapse — user-toggled via the header button. Labels hide, icons stay,
   *  hover popup pattern remains the same. */
  protected readonly collapsed = signal(false);

  /** Per-section collapsed state, persisted to localStorage `hre.sidebar.sections`.
   * Map<key, boolean> — `true` = collapsed (hidden). Default driven by NavSection.defaultOpen. */
  private readonly _sectionsCollapsed = signal<Record<string, boolean>>(this.loadSectionState());
  protected isSectionOpen(s: NavSection): boolean {
    if (!s.key) return true;
    const stored = this._sectionsCollapsed()[s.key];
    if (stored === undefined) return s.defaultOpen ?? true;
    return !stored;
  }
  protected toggleSection(s: NavSection): void {
    if (!s.key) return;
    const isOpen = this.isSectionOpen(s);
    const next = { ...this._sectionsCollapsed(), [s.key]: isOpen };
    this._sectionsCollapsed.set(next);
    try { localStorage.setItem('hre.sidebar.sections', JSON.stringify(next)); } catch { /* ignore */ }
  }
  private loadSectionState(): Record<string, boolean> {
    try {
      const raw = localStorage.getItem('hre.sidebar.sections');
      if (!raw) return {};
      const parsed = JSON.parse(raw);
      return typeof parsed === 'object' && parsed !== null ? parsed : {};
    } catch { return {}; }
  }
  protected readonly isDark = signal(false);
  protected readonly bellOpen = signal(false);

  /** Sidebar toggle icon flips direction to hint what clicking it will do. */
  protected readonly sidebarToggleIcon = computed(() =>
    this.collapsed() ? 'layout-sidebar-left-expand' : 'layout-sidebar-left-collapse',
  );

  /** Title tooltip cho nút thu/mở sidebar — i18n qua I18nService.t() (sync) vì
   *  đây là computed, không phải template context để dùng pipe `| translate`. */
  protected readonly sidebarToggleTitle = computed(() =>
    this.i18n.t(this.collapsed() ? 'common.expandSidebar' : 'common.collapseSidebar'),
  );

  toggleSidebar(): void {
    this.collapsed.update((c) => !c);
    // Sidebar width animates over 220ms — fire a resize event after the transition
    // settles so gridster (dashboard) + echarts (reports) recompute their viewport
    // and the main content claims the freed/given space instead of leaving a strip.
    setTimeout(() => window.dispatchEvent(new Event('resize')), 260);
  }

  /** Which parent groups are expanded (click-to-toggle dropdown). Key = NavItem.key.
   *  Undefined entry falls back to `activeChild(item) !== null` in isParentExpanded(),
   *  so a group auto-opens the first time it contains the active route. */
  private readonly _expandedParents = signal<Record<string, boolean>>({});

  protected toggleParent(item: NavItem): void {
    if (!item.key) return;
    const isOpen = this.isParentExpanded(item);
    this._expandedParents.update((m) => ({ ...m, [item.key!]: !isOpen }));
  }

  protected isParentExpanded(item: NavItem): boolean {
    if (!item.key) return false;
    const stored = this._expandedParents()[item.key];
    if (stored !== undefined) return stored;
    return this.activeChild(item) !== null;
  }

  /** Track active route — used to compute "which child of this parent is active". */
  protected readonly currentUrl = signal<string>(this.router.url);

  constructor() {
    this.router.events
      .pipe(filter((e): e is NavigationEnd => e instanceof NavigationEnd))
      .subscribe((e) => this.currentUrl.set(e.urlAfterRedirects));
  }

  // ===== Permission helpers =====

  protected canSee(item: { perm?: string }): boolean {
    return !item.perm || this.currentUser.has(item.perm);
  }

  protected anyVisible(items: NavItem[]): boolean {
    return items.some((i) => {
      if (i.children) return this.anyVisible(i.children);
      return this.canSee(i);
    });
  }

  /** Return the parent's active child (matched by current URL) or null. */
  protected activeChild(item: NavItem): NavItem | null {
    if (!item.children) return null;
    const url = this.currentUrl();
    for (const c of item.children) {
      if (c.route && (url === c.route || url.startsWith(c.route + '/'))) return c;
    }
    return null;
  }

