  onComingSoon(item: NavItem): void {
    // item.label is an i18n key — resolve it before showing in the toast.
    this.toast.comingSoon(this.i18n.t(item.label));
  }

  toggleDark(): void {
    const dark = !this.isDark();
    this.isDark.set(dark);
    this.doc.documentElement.classList.toggle('dark', dark);
  }

  /** Dev logout — clear localStorage user + hard-reload to /login. */
  logout(): void {
    this.currentUser.clearActiveUser();
    window.location.href = '/login';
  }

  toggleBell(): void {
    this.bellOpen.update((v) => !v);
  }

  async clickNotification(id: string, linkUrl: string | null): Promise<void> {
    await this.notify.markRead(id);
    if (linkUrl) {
      this.router.navigateByUrl(linkUrl);
      this.bellOpen.set(false);
    }
  }

