import { Injectable, inject, signal } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { firstValueFrom } from 'rxjs';

/** Available UI languages. Add new ones here + create matching `public/i18n/<code>.json`. */
export const SUPPORTED_LANGS = ['vi', 'en'] as const;
export type LangCode = (typeof SUPPORTED_LANGS)[number];

export interface LangMeta { code: LangCode; label: string; flag: string; }
export const LANGS: LangMeta[] = [
  { code: 'vi', label: 'Tiếng Việt', flag: '🇻🇳' },
  { code: 'en', label: 'English',    flag: '🇬🇧' },
];

const STORAGE_KEY = 'hre.lang';

/**
 * Thin wrapper over ngx-translate exposing the current language as a signal so any component
 * can `effect()` on it. Persists user choice to localStorage. APP_INITIALIZER already calls
 * translate.use(lang) on boot — this service handles runtime switching after that.
 */
@Injectable({ providedIn: 'root' })
export class I18nService {
  private readonly translate = inject(TranslateService);

  /** Current active language code (mirrors translate.currentLang as a signal). */
  readonly current = signal<LangCode>(this.translate.currentLang as LangCode || 'vi');

  constructor() {
    // Keep signal in sync if ngx-translate fires lang change from elsewhere.
    this.translate.onLangChange.subscribe((e) => {
      if (SUPPORTED_LANGS.includes(e.lang as LangCode)) this.current.set(e.lang as LangCode);
    });
  }

  /** Switch language at runtime + persist user choice. */
  async switch(lang: LangCode): Promise<void> {
    if (!SUPPORTED_LANGS.includes(lang)) return;
    await firstValueFrom(this.translate.use(lang));
    try { localStorage.setItem(STORAGE_KEY, lang); } catch { /* private mode */ }
    this.current.set(lang);
  }

  /** Synchronous translate — same as TranslateService.instant. */
  t(key: string, params?: Record<string, unknown>): string {
    return this.translate.instant(key, params);
  }
}
