import { Injectable } from '@angular/core';

// STUB — bản lab không dùng ng-zorro-antd (main-layout không cần nz- component nào),
// chỉ log console thay cho toast thật để không phải kéo thêm dependency.
export type NotificationType = 'success' | 'error' | 'info' | 'warning';

export interface ConfirmConfig {
  type?: 'warning' | 'danger' | 'info' | 'success';
  title: string;
  content?: string;
  okText?: string;
  cancelText?: string;
  onOk?: () => void;
  onCancel?: () => void;
}

@Injectable({ providedIn: 'root' })
export class NotificationService {
  notify(type: NotificationType, title: string, message?: string): void {
    console.info(`[toast:${type}]`, title, message ?? '');
  }

  success(title: string, message?: string): void {
    this.notify('success', title, message);
  }

  error(title: string, message?: string): void {
    this.notify('error', title, message);
  }

  comingSoon(what?: string): void {
    this.notify('info', 'Tính năng đang phát triển', what ? `${what} chưa được build.` : undefined);
  }

  confirm(config: ConfirmConfig): void {
    console.info('[confirm]', config.title);
    config.onOk?.();
  }
}
