import { Injectable, computed, signal } from '@angular/core';

// STUB — không SignalR/backend thật, chỉ giữ đúng API mà main-layout dùng.
export interface NotificationItem {
  Id: string;
  Kind: string;
  Title: string;
  Body: string | null;
  Severity: string;
  Priority: string;
  LinkUrl: string | null;
  RelatedEntityName: string | null;
  RelatedEntityId: string | null;
  IsRead: boolean;
  ReadAt: string | null;
  CreatedAt: string | null;
}

const MOCK_ITEMS: NotificationItem[] = [
  {
    Id: '1', Kind: 'Approval', Title: 'Đơn nghỉ phép cần duyệt', Body: 'Trần Thu Hà gửi đơn nghỉ phép 03/07.',
    Severity: 'Warning', Priority: 'Normal', LinkUrl: null, RelatedEntityName: null, RelatedEntityId: null,
    IsRead: false, ReadAt: null, CreatedAt: new Date().toISOString(),
  },
  {
    Id: '2', Kind: 'System', Title: 'Kỳ công tháng 6 đã chốt', Body: null,
    Severity: 'Success', Priority: 'Normal', LinkUrl: null, RelatedEntityName: null, RelatedEntityId: null,
    IsRead: true, ReadAt: new Date().toISOString(), CreatedAt: new Date().toISOString(),
  },
];

@Injectable({ providedIn: 'root' })
export class NotifyService {
  readonly items = signal<NotificationItem[]>(MOCK_ITEMS);
  readonly unread = signal<number>(1);
  readonly loading = signal<boolean>(false);
  readonly hasUnread = computed(() => this.unread() > 0);

  async refresh(): Promise<void> {
    /* no-op trong lab */
  }

  async markRead(id: string): Promise<void> {
    this.items.update((arr) => arr.map((n) => (n.Id === id && !n.IsRead ? { ...n, IsRead: true } : n)));
    this.unread.update((n) => Math.max(0, n - 1));
  }

  async markAllRead(): Promise<void> {
    this.items.update((arr) => arr.map((n) => (n.IsRead ? n : { ...n, IsRead: true })));
    this.unread.set(0);
  }
}
