import { registerLocaleData } from '@angular/common';
import localeVi from '@angular/common/locales/vi';
import localeEn from '@angular/common/locales/en';
import { provideHttpClient, HttpClient } from '@angular/common/http';

// ng-zorro date components (Calendar, DatePicker header) format qua Angular
// formatDate với locale → phải register locale data cả 2 ngôn ngữ, không thì NG0701.
registerLocaleData(localeVi);
registerLocaleData(localeEn);
import {
  ApplicationConfig,
  importProvidersFrom,
  provideAppInitializer,
  provideBrowserGlobalErrorListeners,
  inject,
} from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideAnimations } from '@angular/platform-browser/animations';
import { TranslateModule, TranslateService, TranslateLoader } from '@ngx-translate/core';
import { TranslateHttpLoader } from '@ngx-translate/http-loader';
import { firstValueFrom } from 'rxjs';
import { provideNzI18n, vi_VN, en_US, NzI18nService } from 'ng-zorro-antd/i18n';
import { NzModalModule } from 'ng-zorro-antd/modal';
import { provideNzIcons, NZ_ICONS_USED_BY_ZORRO } from 'ng-zorro-antd/icon';
// Vài ant icon common cho props của component (nz-avatar nzIcon, nz-result...) —
// tránh lỗi "icon X not found" abort cả page. Icon MÌNH đặt vẫn dùng Tabler.
import {
  UserOutline, TeamOutline, FileOutline, FolderOutline, SmileOutline, FrownOutline,
  DownloadOutline,
  // Fill icons cho nz-result (success/error/info/warning) — warning KHÔNG nằm trong
  // NZ_ICONS_USED_BY_ZORRO nên icon rỗng (chỉ thấy halo). Đăng ký đủ 4 tông.
  CheckCircleFill, CloseCircleFill, ExclamationCircleFill, WarningFill,
} from '@ant-design/icons-angular/icons';
import {
  provideTablerIcons,
  IconLayoutGrid, IconLayoutDashboard, IconHome,
  IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
  IconBell, IconLogout, IconSelector, IconChevronDown, IconChevronRight, IconCheck,
  IconUserCircle, IconUsers, IconFileText, IconHistory, IconTrendingUp, IconBuilding,
  IconBriefcase, IconArrowUpCircle, IconArrowDownCircle, IconArrowUpRight,
  IconArrowsShuffle, IconStack, IconCurrencyDollar, IconCalendar,
  IconEdit, IconAlertCircle, IconEye, IconList, IconInbox, IconHexagon, IconSettings,
  IconGitBranch, IconGitMerge, IconMail, IconTag, IconCoins, IconMapPin, IconSchool,
  IconAward, IconClock, IconSun, IconMoon, IconUserCog, IconWallet, IconChartBar,
  IconUserX, IconFileCertificate, IconShieldCheck, IconLock,
  IconDownload, IconFilter, IconSearch,
  // extra cho gallery ng-zorro (icon Tabler thay icon ant)
  IconPlus, IconMinus, IconTrash, IconUpload, IconX, IconChevronLeft,
  IconDots, IconDotsVertical, IconStar, IconStarFilled, IconHeart, IconPhone,
  IconInfoCircle, IconCircleCheck, IconAlertTriangle, IconCircleX, IconRefresh,
  IconFolder, IconFile, IconWorld, IconThumbUp, IconArrowRight, IconArrowLeft,
  IconPaperclip, IconPhoto, IconDeviceFloppy, IconCopy, IconShare, IconPrinter,
  IconUser,
} from '@tabler/icons-angular';
import { CurrentUserService, provideHrmIcons } from 'hrm-ui';

import { routes } from './app.routes';

export function hrmTranslateLoader(http: HttpClient): TranslateHttpLoader {
  return new TranslateHttpLoader(http, '/i18n/', '.json');
}

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes),
    provideHttpClient(),
    provideAnimations(),
    provideNzI18n(vi_VN),
    // Icon chrome nội bộ ng-zorro (mũi tên select, close modal, sort table...) — ant tự render.
    // Icon do MÌNH đặt trong template = Tabler (<tabler-icon>), theo icon standard dự án.
    provideNzIcons([...NZ_ICONS_USED_BY_ZORRO, UserOutline, TeamOutline, FileOutline, FolderOutline, SmileOutline, FrownOutline, DownloadOutline, CheckCircleFill, CloseCircleFill, ExclamationCircleFill, WarningFill]),
    importProvidersFrom(
      TranslateModule.forRoot({
        defaultLanguage: 'vi',
        loader: { provide: TranslateLoader, useFactory: hrmTranslateLoader, deps: [HttpClient] },
      }),
      NzModalModule,
    ),
    // Nét icon do DS kiểm soát tập trung (HRM_ICON_STROKE = 1.5). Đổi trong hrm-ui → mọi app đổi theo.
    provideHrmIcons(),
    provideTablerIcons({
      IconLayoutGrid, IconLayoutDashboard, IconHome,
      IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
      IconBell, IconLogout, IconSelector, IconChevronDown, IconChevronRight, IconCheck,
      IconUserCircle, IconUsers, IconFileText, IconHistory, IconTrendingUp, IconBuilding,
      IconBriefcase, IconArrowUpCircle, IconArrowDownCircle, IconArrowUpRight,
      IconArrowsShuffle, IconStack, IconCurrencyDollar, IconCalendar,
      IconEdit, IconAlertCircle, IconEye, IconList, IconInbox, IconHexagon, IconSettings,
      IconGitBranch, IconGitMerge, IconMail, IconTag, IconCoins, IconMapPin, IconSchool,
      IconAward, IconClock, IconSun, IconMoon, IconUserCog, IconWallet, IconChartBar,
      IconUserX, IconFileCertificate, IconShieldCheck, IconLock,
      IconDownload, IconFilter, IconSearch,
      IconPlus, IconMinus, IconTrash, IconUpload, IconX, IconChevronLeft,
      IconDots, IconDotsVertical, IconStar, IconStarFilled, IconHeart, IconPhone,
      IconInfoCircle, IconCircleCheck, IconAlertTriangle, IconCircleX, IconRefresh,
      IconFolder, IconFile, IconWorld, IconThumbUp, IconArrowRight, IconArrowLeft,
      IconPaperclip, IconPhoto, IconDeviceFloppy, IconCopy, IconShare, IconPrinter,
      IconUser,
    }),
    provideAppInitializer(async () => {
      const currentUser = inject(CurrentUserService);
      const translate = inject(TranslateService);
      const nzI18n = inject(NzI18nService);
      const saved = (() => {
        try { return localStorage.getItem('hre.lang'); } catch { return null; }
      })();
      const lang = saved && /^(vi|en)$/.test(saved) ? saved : 'vi';
      translate.addLangs(['vi', 'en']);
      translate.setDefaultLang('vi');
      // NG-ZORRO locale (chrome nội bộ: DatePicker, Table rỗng, Pagination, Select,
      // nút Modal…) + date format phải bám ngôn ngữ. Set ban đầu + theo mỗi lần đổi.
      const applyNzLocale = (l: string) => nzI18n.setLocale(l === 'en' ? en_US : vi_VN);
      applyNzLocale(lang);
      translate.onLangChange.subscribe((e) => applyNzLocale(e.lang));
      await firstValueFrom(translate.use(lang));
      await currentUser.load();
    }),
  ],
};
